// Extrair dados do webhook
const triggerItem = $input.first().json;
const payload = triggerItem.body ?? triggerItem;
const { webhookId, projectId, projectTitle, input, keywords, piiRedactions, embeddingId, callbackUrl, language } = payload;

return [{
  json: {
    webhookId,
    projectId,
    projectTitle,
    embeddingId,
    callbackUrl,
    language: language || 'pt-BR',
    input: typeof input === 'string' ? input : '',
    keywords: Array.isArray(keywords) ? keywords : [],
    piiRedactions: piiRedactions || 0,
    startedAt: new Date().toISOString()
  }
}];

